# Production agent loop, bounds, verification, checkpointing

import anthropic
import json
import time
from pathlib import Path

client = anthropic.Anthropic()

TOOLS = [
    {
        "name": "search",
        "description": (
            "Search for information. Use when you need facts not in your context. "
            "Returns top 5 results with titles and snippets. "
            "Do NOT use for calculations or for content you already have."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "query": {"type": "string", "description": "Search query, 3-8 words"}
            },
            "required": ["query"]
        }
    },
    {
        "name": "write_file",
        "description": (
            "Write content to a file. Use when you need to save a result. "
            "Overwrites if file exists. Path must be under /workspace/."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "path": {"type": "string"},
                "content": {"type": "string"}
            },
            "required": ["path", "content"]
        }
    }
]

def run_agent(
    task: str,
    checkpoint_path: str,
    max_iterations: int = 20,    # hard ceiling, agents fail by never stopping
    max_cost_usd: float = 2.0,   # dollar budget, non-optional
) -> dict:

    # Resume from checkpoint if one exists
    state = load_checkpoint(checkpoint_path)
    if state:
        messages = state["messages"]
        iteration = state["iteration"]
        total_cost = state["total_cost"]
        print(f"Resuming from iteration {iteration}")
    else:
        messages = [{"role": "user", "content": task}]
        iteration = 0
        total_cost = 0.0

    while iteration < max_iterations:
        if total_cost >= max_cost_usd:
            return {"status": "budget_exceeded", "cost": total_cost,
                    "messages": messages}

        response = client.messages.create(
            model="claude-sonnet-4-6",
            max_tokens=4096,
            tools=TOOLS,
            messages=messages
        )

        # Track cost, output tokens are 5x input price, track both
        usage = response.usage
        iteration_cost = (
            usage.input_tokens  * 3.00 / 1_000_000 +
            usage.output_tokens * 15.00 / 1_000_000
        )
        total_cost += iteration_cost
        iteration += 1

        messages.append({"role": "assistant", "content": response.content})

        # Checkpoint after every iteration, resume from here on crash
        save_checkpoint(checkpoint_path, {
            "messages": messages,
            "iteration": iteration,
            "total_cost": total_cost
        })

        if response.stop_reason == "end_turn":
            # Verification gate, harness checks completion, never self-report
            verification = verify_completion(task, messages)
            if verification["complete"]:
                return {"status": "complete", "cost": total_cost,
                        "messages": messages, "verification": verification}
            else:
                # Targeted continuation, tell the model exactly what is missing
                messages.append({
                    "role": "user",
                    "content": (
                        f"Not complete yet. Missing: {verification['missing']}. "
                        "Continue from where you left off."
                    )
                })
                continue

        if response.stop_reason == "tool_use":
            tool_results = []
            for block in response.content:
                if block.type == "tool_use":
                    result = execute_tool(block.name, block.input)
                    tool_results.append({
                        "type": "tool_result",
                        "tool_use_id": block.id,
                        "content": result
                    })
            messages.append({"role": "user", "content": tool_results})

    return {"status": "max_iterations_reached", "cost": total_cost,
            "messages": messages}


def verify_completion(task: str, messages: list) -> dict:
    """Harness-side verification, code or structured check, not model self-report."""
    # Replace with task-specific checks:
    # tests pass, required files exist, required sections present
    # This stub uses a cheap model call; replace with deterministic checks where possible
    check = client.messages.create(
        model="claude-haiku-4-5",       # cheap model for the gate
        max_tokens=200,
        system="Reply ONLY with valid JSON: {complete: bool, missing: str}",
        messages=[{
            "role": "user",
            "content": f"Task: {task}\n\nFinal message: {messages[-1]}"
        }]
    )
    return json.loads(check.content[0].text)

