import re, json, time
from typing import Literal
from anthropic import Anthropic
from sentence_transformers import CrossEncoder

# ── CONFIGURATION ─────────────────────────────────────────────────────────────
NLI_MODEL = "cross-encoder/nli-deberta-v3-small"   # 80ms/claim on CPU; production-ready
FAITHFULNESS_THRESHOLD_HIGH   = 0.4   # below: block entirely
FAITHFULNESS_THRESHOLD_MEDIUM = 0.75  # below: flag and serve with disclaimer
# above MEDIUM threshold: log and serve normally

INJECTION_PATTERNS = [
    re.compile(r"(?i)ignore\s+(all\s+)?(previous|prior)\s+instructions?"),
    re.compile(r"(?i)you\s+are\s+now\s+in\s+\w+\s+mode"),
    re.compile(r"(?i)disregard\s+your\s+(system\s+prompt|guidelines?)"),
    re.compile(r"(?i)print\s+(the\s+)?(system\s+prompt|full\s+instructions?)"),
    re.compile(r"(?i)base64\s+decode"),
]

# ── LAYER 1: INPUT SCREENING ──────────────────────────────────────────────────

def screen_input(text: str) -> tuple[bool, str]:
    """Fast structural screening before any model call."""
    for pattern in INJECTION_PATTERNS:
        if pattern.search(text):
            return False, f"injection_pattern: {pattern.pattern}"
    if contains_pii(text):
        return False, "pii_detected"
    return True, ""

def contains_pii(text: str) -> bool:
    """Heuristic PII detection, replace with a proper NER model for production."""
    pii_patterns = [
        re.compile(r"\b\d{3}-\d{2}-\d{4}\b"),           # SSN
        re.compile(r"\b4[0-9]{12}(?:[0-9]{3})?\b"),      # Visa card
        re.compile(r"\b[A-Z]{2}\d{6,9}\b"),              # Passport
    ]
    return any(p.search(text) for p in pii_patterns)

# ── LAYER 2: PER-CLAIM FAITHFULNESS GATE ─────────────────────────────────────

def extract_claims(answer: str) -> list[str]:
    """Decompose answer into atomic verifiable claims."""
    client = Anthropic()
    resp = client.messages.create(
        model="claude-haiku-4-5",
        max_tokens=1024,
        output_config={
            "format": {
                "type": "json_schema",
                "schema": {
                    "type": "object",
                    "properties": {
                        "claims": {"type": "array", "items": {"type": "string"}}
                    },
                    "required": ["claims"],
                    "additionalProperties": False,
                },
            }
        },
        messages=[{
            "role": "user",
            "content": f"""Extract every distinct factual claim from this answer as a list of short, self-contained sentences.
Each claim should be independently verifiable.
Return JSON: {{"claims": ["claim1", "claim2", ...]}}

Answer: {answer}"""
        }]
    )
    text = next(b.text for b in resp.content if b.type == "text")
    return json.loads(text).get("claims", [answer])

def nli_score_claims(claims: list[str], context: str) -> list[dict]:
    """Score each claim against context using NLI model. Returns per-claim results."""
    nli = CrossEncoder(NLI_MODEL)   # cache this in production, load once at startup
    pairs = [(context[:512], claim) for claim in claims]  # truncate context to model max
    # NLI labels: 0=contradiction, 1=neutral, 2=entailment
    scores = nli.predict(pairs, apply_softmax=True)
    results = []
    for claim, score_vec in zip(claims, scores):
        entailment_prob = float(score_vec[2])  # index 2 = entailment
        results.append({
            "claim": claim,
            "entailment": entailment_prob,
            "label": "entailed" if entailment_prob > 0.7 else ("neutral" if entailment_prob > 0.4 else "contradicted")
        })
    return results

def faithfulness_gate(answer: str, context: str) -> dict:
    """Full per-claim faithfulness check with risk tier classification."""
    claims = extract_claims(answer)
    claim_results = nli_score_claims(claims, context)
    unsupported = [r for r in claim_results if r["label"] != "entailed"]
    # overall faithfulness = fraction of claims that are entailed
    overall = sum(1 for r in claim_results if r["label"] == "entailed") / max(len(claim_results), 1)
    risk_tier = classify_risk(overall)
    return {
        "overall_faithfulness": overall,
        "risk_tier": risk_tier,
        "claims": claim_results,
        "unsupported_claims": [r["claim"] for r in unsupported],
    }

RiskTier = Literal["low", "medium", "high"]

def classify_risk(faithfulness_score: float) -> RiskTier:
    if faithfulness_score < FAITHFULNESS_THRESHOLD_HIGH:
        return "high"
    if faithfulness_score < FAITHFULNESS_THRESHOLD_MEDIUM:
        return "medium"
    return "low"

# ── LAYER 3: RISK-TIER ROUTING ────────────────────────────────────────────────

def route_by_risk(gate_result: dict, answer: str) -> dict:
    tier = gate_result["risk_tier"]
    score = gate_result["overall_faithfulness"]
    if tier == "high":
        # Block, don't serve, log the failure for labeling queue
        log_quality_event("hallucination_block", gate_result)
        return {
            "served": False,
            "response": "I don't have reliable information to answer this question.",
            "tier": "high", "faithfulness": score
        }
    if tier == "medium":
        # Flag and serve, add disclaimer, log for review
        log_quality_event("hallucination_flag", gate_result)
        disclaimer = "\n\n*Note: Some parts of this answer may not be fully supported by the available context. Please verify before relying on this information.*"
        return {
            "served": True,
            "response": answer + disclaimer,
            "tier": "medium", "faithfulness": score
        }
    # Low risk, log and serve normally
    log_quality_event("hallucination_ok", gate_result)
    return {"served": True, "response": answer, "tier": "low", "faithfulness": score}

def log_quality_event(event_type: str, details: dict) -> None:
    print(json.dumps({"event": event_type, "ts": time.time(), **details}))

# ── LAYER 4: QUARANTINE EXTERNAL CONTENT ─────────────────────────────────────

def quarantine_external(content: str, source_label: str) -> str:
    """Wrap external content in explicit trust-boundary markers."""
    return f"<external source='{source_label}' trust='untrusted'>\n{content}\n</external>"

# ── OPTION A: RAGAS FAITHFULNESS (ALTERNATIVE TO NLI GATE) ───────────────────

def check_faithfulness_ragas(question: str, answer: str, contexts: list[str]) -> float:
    """Use RAGAS faithfulness metric as an alternative to the NLI gate."""
    from ragas import evaluate
    from ragas.metrics import faithfulness
    from datasets import Dataset
    data = Dataset.from_dict({
        "question": [question],
        "answer": [answer],
        "contexts": [contexts],
    })
    result = evaluate(data, metrics=[faithfulness])
    return float(result["faithfulness"])

# ── MAIN PIPELINE ─────────────────────────────────────────────────────────────

def answer(query: str, retrieved_docs: list[str], raw_answer: str) -> dict:
    # Layer 1: input screening
    safe, reason = screen_input(query)
    if not safe:
        return {"served": False, "response": f"Request blocked: {reason}"}

    # Layer 2: faithfulness gate (NLI per-claim)
    context = "\n\n".join(quarantine_external(doc, f"doc_{i}") for i, doc in enumerate(retrieved_docs))
    gate = faithfulness_gate(raw_answer, context)

    # Layer 3: risk-tier routing
    return route_by_risk(gate, raw_answer)

