# Retrieval-index MCP server on the 2026-07-28 spec (Python SDK `mcp` 2.0.0).
# v2 renamed FastMCP -> MCPServer (mcp.server.fastmcp.* -> mcp.server.mcpserver.*);
# the decorator API itself is unchanged.
import base64, hashlib, hmac, json, os, sys, time
from mcp.server.mcpserver import MCPServer

from docs_index import INDEX, COLLECTIONS, auth, redeem_once  # your code

mcp = MCPServer("docs-index")
STATE_KEY = os.environ["MCP_STATE_KEY"].encode()   # a vaulted secret, never an argument
TTL_S = 300

def current_principal() -> str:
    """Identity comes from the transport's auth context - the OAuth subject on
    Streamable HTTP, the launching user on stdio. NEVER from a tool argument."""
    return auth.principal_for_current_request()

# -- Stateless core: no initialize handshake, no Mcp-Session-Id, no sessions. --
# Cross-call state is a server-minted handle that travels back as an ordinary
# argument, so it is ATTACKER-CONTROLLED until you verify it.
def mint_state(principal: str, claims: dict) -> str:
    body = {"sub": principal, "exp": int(time.time()) + TTL_S, **claims}
    raw = json.dumps(body, sort_keys=True, separators=(",", ":")).encode()
    sig = hmac.new(STATE_KEY, raw, hashlib.sha256).digest()   # 32 bytes, fixed width
    return base64.urlsafe_b64encode(raw + sig).decode()

def open_state(token: str, principal: str) -> dict:
    blob = base64.urlsafe_b64decode(token.encode())
    raw, sig = blob[:-32], blob[-32:]   # split on width, NOT on a delimiter byte:
                                        # a sha256 digest can contain any byte value
    if not hmac.compare_digest(sig, hmac.new(STATE_KEY, raw, hashlib.sha256).digest()):
        raise ValueError("state failed its integrity check")   # MUST reject
    body = json.loads(raw)
    if body["sub"] != principal:
        raise ValueError("state is bound to a different principal")
    if body["exp"] < time.time():
        raise ValueError("state expired; start the request again")
    if not redeem_once(token):        # signing binds it; it does not make it single-use
        raise ValueError("state already redeemed")
    return body

# -- Tools are model-controlled. The description is prompt content, re-read every
# call - which is exactly why a server that mutates it later is a rug pull.
@mcp.tool()
def search_docs(query: str, collection: str = "public", top_k: int = 8) -> dict:
    """Search the engineering docs index and return ranked, citable passages.

    USE WHEN the user asks about internal APIs, runbooks, or architecture decisions.
    DO NOT USE for source code (use search_code) or tickets (use search_issues).
    Returns at most 8 passages, best score first, each with a citable doc_id.
    Example: search_docs(query="how do we rotate the signing key", collection="platform")
    """
    if collection not in COLLECTIONS:                          # instructive errors
        raise ValueError(f"unknown collection {collection!r}; use one of {sorted(COLLECTIONS)}")
    hits = INDEX.search(query, collection, k=min(top_k, 8), principal=current_principal())
    return {"passages": [{"doc_id": h.id, "score": h.score, "text": h.text} for h in hits]}

# Header mirroring (SEP-2243): mark a PRIMITIVE param (string/integer/boolean -
# `number` is not permitted) in the tool's published inputSchema, and the client
# emits Mcp-Param-Collection so a gateway routes and rate-limits without ever
# parsing the JSON body. The annotation your schema must carry:
#     "collection": {"type": "string", "x-mcp-header": true}

# -- Resources are application-controlled, and resources/read is cacheable. --
@mcp.resource("docs://collections")
def list_collections() -> dict:
    return {"ttlMs": 300_000, "cacheScope": "public",    # CacheableResult envelope, SEP-2549
            "collections": sorted(COLLECTIONS)}

# -- MRTR (SEP-2322): servers no longer initiate requests. To ask the user
# something, return resultType "input_required"; the client gathers the answer and
# RETRIES the same call under a NEW JSON-RPC id, carrying inputResponses + state.
@mcp.tool()
def export_collection(collection: str,
                      inputResponses: dict | None = None,
                      requestState: str | None = None) -> dict:
    """Export a whole collection to the user's workspace. Asks for confirmation first."""
    who = current_principal()
    digest = hashlib.sha256(f"export_collection:{collection}".encode()).hexdigest()
    if inputResponses is None:
        return {
            "resultType": "input_required",
            "inputRequests": {"confirm": {"method": "elicitation/create",
                                          "params": {"message": f"Export {collection}?"}}},
            "requestState": mint_state(who, {"dig": digest}),
        }
    claims = open_state(requestState or "", who)      # principal + TTL + single-use
    if claims["dig"] != digest:                       # replay onto a DIFFERENT request
        raise ValueError("state does not match this request")
    if inputResponses["confirm"].get("action") != "accept":
        return {"resultType": "complete", "exported": 0, "reason": "declined"}
    return {"resultType": "complete", "exported": INDEX.export(collection, principal=who)}

if __name__ == "__main__":
    print("docs-index ready", file=sys.stderr)   # stdout IS the protocol - log to stderr
    mcp.run(transport="stdio")                   # remote: Streamable HTTP + Origin check
